import{_ as l,C as o,o as d,c as m,j as a,a as s,E as e,a2 as i}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"Entretenir la mémoire","description":"","frontmatter":{"title":"Entretenir la mémoire"},"headers":[],"relativePath":"agent/entretenir.md","filePath":"agent/entretenir.md"}'),u={name:"agent/entretenir.md"};function p(h,r,g,f,_,v){const n=o("AskExample"),t=o("Ask"),c=o("Capture");return d(),m("div",null,[r[0]||(r[0]=a("h1",{id:"entretenir-la-memoire",tabindex:"-1"},[s("Entretenir la mémoire "),a("a",{class:"header-anchor",href:"#entretenir-la-memoire","aria-label":'Permalink to "Entretenir la mémoire"'},"​")],-1)),r[1]||(r[1]=a("p",null,"Ce parcours sert à garder le dossier en bon état : repérer les défauts (lien cassé, note orpheline, frontmatter illisible…), les réparer, et ranger (renommer, déplacer, fusionner, retirer) sans casser les liens. L'application sait le faire seule pour une part ; l'agent prend le reste.",-1)),r[2]||(r[2]=a("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[s("Ce que vous demandez à l'agent "),a("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),e(n,{tool:"mem_health_scan"}),e(n,{tool:"mem_health_repair"}),e(t,{say:"Applique cette réparation.",verb:"mem_health_repair",family:"maintenance",args:'{"apply":true,"plan_id":"3f9a1c0e"}'}),e(t,{say:"Quelles tâches de santé me reviennent ? Les résumés à composer, d'abord.",verb:"mem_health_tasks",family:"maintenance",args:'{"kind":"compose-summary"}'}),e(n,{tool:"mem_rename"}),e(n,{tool:"mem_move"}),e(t,{say:"Applique ce déplacement.",verb:"mem_move",family:"structure",args:'{"path":"20-knowledge/runner.md","to":"20-knowledge/architecture/runner.md","apply":true}'}),e(t,{say:"Annule le dernier déplacement.",verb:"mem_move_undo",family:"structure"}),e(t,{say:"Retire la note 20-knowledge/note-de-test.md : c'est un doublon de runner.md.",verb:"mem_remove",family:"structure",args:'{"path":"20-knowledge/note-de-test.md","confirm":true,"reason":"Doublon de runner.md."}'}),e(t,{say:"Finalement, remets cette note en place.",verb:"mem_restore",family:"structure",args:'{"path":"20-knowledge/note-de-test.md"}'}),r[3]||(r[3]=i('<h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><h3 id="controler-puis-reparer" tabindex="-1">Contrôler, puis réparer <a class="header-anchor" href="#controler-puis-reparer" aria-label="Permalink to &quot;Contrôler, puis réparer&quot;">​</a></h3><ol><li><a href="/reference/mcp/maintenance.html#mem-health-scan"><code>mem_health_scan</code></a> audite le vault. <strong>Lecture seule</strong>, en toutes circonstances. <code>category</code> restreint l&#39;audit à une catégorie (la liste est dans la <a href="/reference/mcp/maintenance.html#mem-health-scan">référence</a>). Chaque constat dit qui peut le réparer : <code>stage</code> vaut <code>app</code> (l&#39;étape de réparation automatique), <code>agent</code> (une tâche pour l&#39;agent) ou <code>none</code> (avec la raison).</li><li><a href="/reference/mcp/maintenance.html#mem-health-repair"><code>mem_health_repair</code></a> applique les correctifs dont la réponse est unique et sûre. <strong>Par défaut c&#39;est un essai à blanc</strong> : la réponse porte un <code>plan_id</code>, le nombre de corrections et les fichiers concernés, et rien n&#39;est écrit. Avec <code>apply: true</code>, l&#39;agent doit redonner ce <code>plan_id</code> : sans lui, ou si la mémoire a changé depuis, <strong>rien n&#39;est écrit</strong>. Aucun autre paramètre n&#39;est accepté (<code>dry_run</code> est refusé), et rien n&#39;est jamais supprimé.</li><li><a href="/reference/mcp/maintenance.html#mem-health-tasks"><code>mem_health_tasks</code></a> liste ce qui demande du jugement : résumé à composer, note orpheline à rattacher, lien sans cible sûre, conflit de fusion, dépôt déplacé. <code>kind</code> filtre par genre, <code>limit</code> (30 par défaut) et <code>cursor</code> paginent. Chaque tâche nomme les outils à employer et son critère de fin : le constat disparaît du scan. L&#39;agent traite chaque tâche, puis relance <code>mem_health_scan</code> pour vérifier.</li></ol><h3 id="ranger" tabindex="-1">Ranger <a class="header-anchor" href="#ranger" aria-label="Permalink to &quot;Ranger&quot;">​</a></h3><p>Ces outils <strong>réécrivent aussi les liens</strong> qui visent ce qu&#39;ils déplacent (wikiliens, liens Markdown, frontmatter), dans tout le vault. <code>rewrite_links: false</code> désactive cette réécriture pour <code>mem_rename</code>, <code>mem_merge</code> et <code>mem_reclass</code>.</p><ul><li><a href="/reference/mcp/structure.html#mem-move"><code>mem_move</code></a> renomme ou déplace un fichier ou un dossier. <strong>Sans <code>apply</code>, il rend le plan sans rien écrire</strong> : fichiers déplacés, chaque lien avant et après, liens laissés, avertissements, <code>empreinte</code>. Avec <code>apply: true</code>, il applique ; si <code>empreinte</code> est donnée et que le vault a changé depuis, rien n&#39;est écrit. Il refuse une cible occupée, un nom invalide, un dossier protégé, une opération git en cours, ou un plan qui casserait un lien.</li><li><a href="/reference/mcp/structure.html#mem-rename"><code>mem_rename</code></a> renomme un projet ou un domaine (<code>old_slug</code>, <code>new_slug</code>) ; <a href="/reference/mcp/structure.html#mem-merge"><code>mem_merge</code></a> fusionne deux projets ou deux domaines de même nature (<code>source_slug</code>, supprimé après fusion, dans <code>target_slug</code>) ; <a href="/reference/mcp/structure.html#mem-reclass"><code>mem_reclass</code></a> change la portée (<code>scope</code>) ou la zone (<code>zone</code>) d&#39;une note. Ces trois outils écrivent <strong>dès l&#39;appel</strong> : ils n&#39;ont pas d&#39;essai à blanc. Pour revenir en arrière, voir <code>mem_move_undo</code> ci-dessous.</li><li><a href="/reference/mcp/structure.html#mem-move-undo"><code>mem_move_undo</code></a> annule la <strong>dernière</strong> opération de déplacement du vault (<code>mem_move</code>, <code>mem_rename</code>, <code>mem_reclass</code>, <code>mem_merge</code>, ou le même geste fait dans l&#39;application) : fichiers et liens reviennent à leur état d&#39;avant. Il refuse si un fichier touché a changé depuis.</li></ul><h3 id="retirer" tabindex="-1">Retirer <a class="header-anchor" href="#retirer" aria-label="Permalink to &quot;Retirer&quot;">​</a></h3><p><a href="/reference/mcp/structure.html#mem-remove"><code>mem_remove</code></a> <strong>déplace</strong> une note vers la corbeille du vault (<code>.trash/</code>), avec une note jointe (date, motif, ancien chemin) ; il ne supprime jamais. Ses gardes :</p><ul><li>une note créée par ce serveur pendant la session en cours se retire librement ; pour <strong>toute autre</strong>, <code>confirm: true</code> <strong>et</strong> <code>reason</code> (non vide) sont exigés ;</li><li>une note citée par d&#39;autres est refusée, avec la liste des citants ; <code>force: true</code> la retire quand même et rend chaque lien devenu pendant ;</li><li>il refuse <code>index.md</code>, <code>context.md</code>, <code>history.md</code>, <code>.obsidian/</code> et <code>.trash/</code>, et tout retrait pendant une opération git en cours ;</li><li>il écrit une ligne d&#39;audit dans <code>99-meta/migrations/removals.md</code>. Une note déjà poussée reste dans l&#39;historique git.</li></ul><p><a href="/reference/mcp/structure.html#mem-restore"><code>mem_restore</code></a> la remet en place, octet pour octet, et refuse si un fichier occupe déjà son chemin d&#39;origine : rien n&#39;est jamais écrasé.</p><p>D&#39;autres outils de rangement existent, par exemple <a href="/reference/mcp/structure.html#mem-attach"><code>mem_attach</code></a> (rattacher une note orpheline à un projet ou un domaine) ou <a href="/reference/mcp/structure.html#mem-accept-dangling"><code>mem_accept_dangling</code></a> (déclarer un lien mort volontaire) ; ils sont dans la <a href="/reference/mcp/structure.html">Référence MCP</a>.</p><h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2>',12)),e(c,{name:"accueil",alt:"L'accueil de Kessho : en bas de la fenêtre, la barre d'état affiche la santé de la mémoire (SANTÉ 100 %), l'état git et le compte des agents."}),r[4]||(r[4]=i('<ul><li><strong>La santé.</strong> La barre d&#39;état affiche la <strong>SANTÉ</strong> de la mémoire, et l&#39;accueil porte le <strong>Score de santé de la mémoire</strong>. Il compte les anomalies et sépare ce que l&#39;application répare seule de ce qui revient à un agent (« N tâches pour un agent », avec <strong>Copier la consigne</strong>). <strong>Préparer la réparation</strong> suit le même principe en deux temps que <code>mem_health_repair</code> : un plan, puis <strong>Appliquer</strong> ; un plan périmé est refusé. Voir <a href="/guide/home.html">Accueil</a>.</li><li><strong>Ranger et retirer.</strong> Dans une zone, le menu d&#39;une note propose <strong>Renommer</strong>, <strong>Déplacer</strong> et <strong>Retirer</strong>, avec l&#39;aperçu des liens à mettre à jour et un bouton <strong>Annuler</strong> pour revenir en arrière ; <strong>Retirer</strong> envoie la note à la corbeille (<code>.trash</code>) et propose <strong>Retirer quand même</strong> quand d&#39;autres notes la citent. Voir <a href="/guide/zones.html">Zones</a>.</li><li><strong>Ce que l&#39;agent vient de changer.</strong> Le <strong>témoin de fraîcheur</strong> s&#39;allume après chaque écriture d&#39;agent et nomme la zone touchée ; <strong>Relire</strong> recharge l&#39;écran (voir <a href="/guide/zones.html">Zones</a>).</li></ul>',1))])}const k=l(u,[["render",p]]);export{b as __pageData,k as default};
